import React from 'react';

function RiskMeter({ score }) {

  return (
    <div>

      <div className="meter-labels">
        <span>GOOD</span>
        <span>BAD</span>
      </div>

      <div className="meter">

        <div
          className="meter-fill"
          style={{ width: `${score}%` }}
        >
          {score}%
        </div>

      </div>

    </div>
  );
}

export default RiskMeter;
